/* Update of the oClass 52 moby: follows its target at a hover height above the hero, with a voice while it moves,
 * and bursts or is removed in its last states.
 * Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/shared/gameplay/entities/002c5990.c, FUN_L09_002c5990. */
void seeker_update(struct Moby *moby) {
    SeekerVars *vars = (SeekerVars *)moby->pvars;
    struct Moby *target;
    Vec4 vel;
    s32 mode;
    s32 voice;
    f32 dist;
    f32 z;
    f32 height;
    f32 limit;
    f32 diff;
    VoicePoolRow *slot;

    update_seeker_damage_and_target_r(moby);
    target = vars->target;
    Manipulator_ApplyScale_r(moby, 0, vars->unk280, 2.7f);
    if (moby->visible != 0 && fast_vec_dist(&moby->pos, &gaspar_camera_pos_r) < 29.0f) {
        set_ground_height_band_r(moby);
        moby->shadow_range = 0x17;
    }
    mode = seeker_state_dispatch_mode;
    if (mode == 2) {
        return;
    }
    switch (moby->state) {
        case 0:
            vars->unk20 = 3.0f;
            vars->unk24 = 3;
            vars->unk28 = 2;
            vars->unk5A = 6;
            vars->unk58 = 8;
            if (vars->unk180 == -1) {
                STUB_printf_r(seeker_invalid_bound_path_format, moby->save_id);
                DeleteMoby_r(moby);
                break;
            }
            MoveCtl_Init(&vars->unkD0);
            vars->unkDC = 0.5f;
            vars->unkD8 = 0.5f;
            vars->unkD0 = truncate_float_to_s32_r(512.0f);
            vars->speed = g_frame_time_r * 7.75f;
            moby->state = 1;
            if (moby->prev_seq != 1) {
                MobyBlendAnimation_r(moby, 1, 0, scale_ticks(10));
            }
            vars->voice = -1;
            break;
        case 1:
            moby->pos.z += (probe_ground_height(&moby->pos, 0, 0.5f) + 0.5f - moby->pos.z) * 0.1f;
            SteerAngleWithVelocity_v(&moby->rot.z, fast_atan2(target->pos.x - moby->pos.x, target->pos.y - moby->pos.y),
                                     &vars->heading_speed, g_frame_time_sq_r * 8.726646f, g_frame_time_sq_r * 8.726646f,
                                     g_frame_time_r * 12.566371f);
            if (moby->anim_flags & 2) {
                if (random_integer_below(0x13) == 0) {
                    if (moby->prev_seq != 2) {
                        MobyBlendAnimation_r(moby, 2, 0, random_int_between(7, 12));
                    }
                } else if (moby->prev_seq != 1) {
                    MobyBlendAnimation_r(moby, 1, 0, random_int_between(7, 14));
                }
                moby->anim_speed = random_float_between(0.95f, 1.05f);
            }
            if (vars->unk164 != 2) {
                if (moby->group != 0xFF) {
                    alert_group_e81e0(moby->group, 1);
                }
                if (vars->voice == -1) {
                    vars->voice = Moby_PlaySound_r(1, 4, moby);
                }
                vars->moving = 1;
                moby->state = 2;
            }
            break;
        case 3:
            if (moby->anim_flags & 2) {
                if (moby->group != 0xFF) {
                    alert_group_e81e0(moby->group, 1);
                }
                vars->moving = 1;
                moby->state = 4;
                if (vars->voice == -1) {
                    vars->voice = Moby_PlaySound_r(1, 4, moby);
                }
                if (moby->prev_seq != 4) {
                    MobyBlendAnimation_r(moby, 4, 0, scale_ticks(10));
                }
                if (vars->timer == 0) {
                    vars->timer = scale_ticks(180);
                }
            }
            break;
        case 2:
        case 4:
            z = moby->pos.z;
            SteerAngleWithVelocity_v(&moby->rot.z, fast_atan2(target->pos.x - moby->pos.x, target->pos.y - moby->pos.y),
                                     &vars->heading_speed, g_frame_time_sq_r * 8.726646f, g_frame_time_sq_r * 8.726646f,
                                     g_frame_time_r * 12.566371f);
            dist = vec_distance_xy(&moby->pos, &target->pos);
            if (dist > 1.9f) {
                vars->moving = 1;
            }
            if (dist < 1.4f) {
                vars->moving = 0;
            }
            if (vars->moving != 0) {
                vel.f[0] = FastCos(moby->rot.z) * vars->speed;
                vel.f[1] = FastSin(moby->rot.z) * vars->speed;
                vel.f[2] = 0.0f;
                diff = g_hero.motion.pos.f[2] + 0.8f - z;
                if (moby->pos.z < g_hero.motion.pos.f[2] + 0.8f) {
                    diff *= 0.1f;
                } else {
                    diff *= 0.05f;
                }
                vel.f[2] += diff;
                limit = frame_scale_r * 0.3f;
                if (vel.f[2] > limit) {
                    vel.f[2] = limit;
                } else {
                    limit = frame_scale_r * -0.3f;
                    if (vel.f[2] < limit) {
                        vel.f[2] = limit;
                    }
                }
                move_4318_v(moby, &vel, 0, 0.0f, 0.5f, 0.0f);
            } else {
                qzero(&vel);
                diff = g_hero.motion.pos.f[2] + 0.2f - z;
                if (moby->pos.z < g_hero.motion.pos.f[2] + 0.2f) {
                    diff *= 0.1f;
                } else {
                    diff *= 0.05f;
                }
                vel.f[2] += diff;
                limit = frame_scale_r * 0.3f;
                if (vel.f[2] > limit) {
                    vel.f[2] = limit;
                } else {
                    limit = frame_scale_r * -0.3f;
                    if (vel.f[2] < limit) {
                        vel.f[2] = limit;
                    }
                }
                move_4318_v(moby, &vel, 0, 0.0f, 0.5f, 0.0f);
            }
            if (dist < 6.0f && moby->state == 2) {
                moby->state = 3;
                if (moby->prev_seq != 3) {
                    MobyBlendAnimation_r(moby, 3, 0, scale_ticks(10));
                }
            }
            break;
        case 5:
            height = moby->pos.z;
            mine_fall_r(moby, &vars->vel);
            moby->pos.z = height;
            vars->vel.f[2] = 0.0f;
            if (FastVecLength_r(&vars->vel) < g_frame_time_r * 2.0f) {
                if (vars->voice == -1) {
                    vars->voice = Moby_PlaySound_r(1, 4, moby);
                }
                vars->moving = 1;
                moby->state = 4;
                if (vars->timer == 0) {
                    vars->timer = scale_ticks(180);
                }
            }
            break;
        case 6:
            voice = vars->voice;
            if (voice != -1) {
                slot = (VoicePoolRow *)(voice_pool + voice * 0x70);
                if (slot->owner == moby && slot->state != 0) {
                    Sound_StopSlot(voice);
                }
            }
            vars->voice = -1;
            if (mine_fall_r(moby, &vars->vel) & 0x121) {
                cart_burst(moby, &moby->pos, 0, 0.5f, 13.0f);
                DeleteMoby_r(moby);
            }
            break;
        case 7:
            SetDeathBits_r(moby, 0, -1);
            voice = vars->voice;
            if (voice != -1) {
                slot = (VoicePoolRow *)(voice_pool + voice * 0x70);
                if (slot->owner == moby && slot->state != 0) {
                    Sound_StopSlot(voice);
                }
            }
            vars->voice = -1;
            clear_u64_value_r(&vel);
            func_L00_0025F4A8_2C6B30(moby, &vel, &moby->pos, 10, 2.0f, 1.0f, 4.0f, 2.0f, 9.0f, 1.0f, 15.0f, 3, 0x10, 0,
                                     0, 0, -1, 0);
            DeleteMoby_r(moby);
            break;
    }
}
