/* Enemy update while it chases: takes hits (the result of ComputeHitResponse picks the reaction),
 * re-rolls its retreat timer and steers along its path or straight at the target.
 * In the steering arms the goal pointer and the "lost" code (2) are set in each arm: retail loads 2 in
 * both arms and keeps the goal in a saved register across the arm's call. */
void update_seeker_damage_and_target(Moby *m) {
    char vec[16];
    int flag;
    float a1;
    float ang1;
    float ang2;
    Data_2C73D0 *d;
    Hit_2C73D0 *r;
    int st;
    int res;
    int lost;

    d = (struct Data_2C73D0 *)m->pvars;
    if (m->state == 0) {
        return;
    }
    m->scale = m->scale + ((((Cls *)m->pclass)->scale * D_L09_00161494_2C73D0) - m->scale) * 0.1f;
    if (fast_dec_timer(&d->timer) == 2) {
        m->state = 7;
        return;
    }
    if (d->timer == scale_ticks(0xA) || d->timer == scale_ticks(0x14) || d->timer == scale_ticks(0x28) ||
        d->timer == scale_ticks(0x3C) || d->timer == scale_ticks(0x78) || d->timer == scale_ticks(0xB3)) {
        d->reactTime = 0xF0;
        RerollEffectCounter(m, d->react);
    }
    a1 = 0.0f;
    r = MobyGetHitMessage_r(m, 0x330000, 0);
    st = ComputeHitResponse_r(m, r, &d->health, 0, &flag, &a1, 0, 4);
    if (flag != 1 && m->state != 6) {
        d->health = d->health - a1;
        if (d->health <= 0.0f) {
            st = 1;
        }
        d->f90 = truncate_float_to_s32_r2(512.0f);
        d->f80 = D_L09_00161480_2C73D0 * g_frame_time_sq_r2;
        d->f84 = g_frame_time_sq_r2 * 30.0f;
        d->f98 = 0.0f;
        d->f94 = 1;
        d->bAD = 0;
        Moby_PlaySound_r2(8, 0, m);

        switch (st) {
            case 9:
            case 10:
                d->reactTime = 0xFA;
                break;
            case 3:
            case 4:
            case 5:
            case 6:
            case 7:
            case 8:
                d->fC0 = 3.0f;
                d->fC4 = 6.0f;
                d->f88 = D_L09_00161488_2C73D0 * g_frame_time_r2;
                d->f8C = 0.0f;
                ang1 = fast_atan2(m->pos.x - r->owner->pos.x, m->pos.y - r->owner->pos.y);
                *(Q_2C73D0 *)vec = r->pos;
                trooper_knockback_arc(vec, &ang1, &d->f88, &d->f8C);
                InitKnockback(m, d->f70, ang1, 4, 1, 0);
                m->state = 5;
                if (m->group != 0xFF) {
                    alert_group_e81e0(m->group, 1);
                }
                d->reactTime = 0x78;
                break;
            case 1:
            case 2:
                m->flags &= 0xEFFF;
                d->f80 = D_L09_00161480_2C73D0 * g_frame_time_sq_r2;
                d->f88 = D_L09_00161490_2C73D0 * g_frame_time_r2;
                d->f8C = D_L09_0016148C_2C73D0 * g_frame_time_r2;
                d->fC0 = 14.0f;
                d->fC4 = 28.0f;
                ang2 = fast_atan2(m->pos.x - r->owner->pos.x, m->pos.y - r->owner->pos.y);
                *(Q_2C73D0 *)vec = r->pos;
                trooper_knockback_arc(vec, &ang2, &d->f88, &d->f8C);
                InitKnockback(m, d->f70, ang2, 4, 1, 0);
                SetDeathBits(m, 0, -1);
                m->state = 6;
                d->reactTime = 0xF0;
                break;
            case 0:
            case 11:
            default:
                break;
        }
        RerollEffectCounter(m, d->react);
    }
    m->hit_slot = 0xFF;
    StepColorFade(m, d->react);
    if (d->f38 != 0 || m->command == 1) {
        d->retreat = truncate_float_to_s32_r2(multiply_global_factor(random_float_between(180.0f, 240.0f)));
        d->f38 = 0;
        m->command = 0;
    }
    fast_dec_timer(&d->retreat);
    if (random_integer_below(4) == 0) {
        float *tgt;
        if (d->retreat != 0) {
            d->reach = 24.0f;
            tgt = d->target;
            res = FindNearestTargetMoby(m, tgt, 24.0f);
            lost = 2;
        } else {
            Path *tb;
            d->reach = 12.0f;
            tb = gaspar_paths_r[d->path];
            tgt = d->target;
            res = FindNearestEligibleMoby_r(m, tgt, 12.0f, 0, 0, tb->pts, tb->count);
            lost = 2;
        }
        if (res != lost && d->retreat == 0) {
            if (d->reach < vec_distance_xy(&m->pos, tgt)) {
                d->f164 = lost;
            } else if (3.0f < absolute_float(m->pos.z - d->target[2])) {
                d->f164 = lost;
            }
        }
    } else {
        Moby *q = d->f160;
        if (q != 0 && q->state != 0xFE && q->state != 0xFD) {
            qcopy(d->target, &q->pos);
        } else {
            d->f160 = 0;
            d->f164 = 2;
        }
    }
    if (d->f160 == 0) {
        d->f160 = *(Moby **)&g_hero.moby;
    }
}
