/* ticks down a timer against a hit check, then reacts: either ends or switches to state 2 */
void process_spawner_hit_record(char *moby, char *d) {
    int n;
    struct HitMessage *m = (struct HitMessage *)MobyGetHitMessage(moby, 0xC30000, 0);
    ComputeHitResponse(moby, m, d + 0x20, 0, &n, 0, 0, 4);
    if (n >= 2) {
        float v = *(float *)(d + 0x20) - m->damage;
        *(float *)(d + 0x20) = v;
        if (v > 0.0f) {
            d[0x67] = 0x5A;
            RerollEffectCounter(moby, (short *)(d + 0x60));
        } else {
            if (g_current_level_index == LEVEL_GEMLIK && absolute_float(g_hero.motion.pos.f[2] - 248.0f) < 4.0f) {
                SetDeathBits(moby, 0x200, -1);
            } else {
                SetDeathBits(moby, 0, -1);
            }
            moby[0x20] = 2;
            d[0x67] = 0x78;
            RerollEffectCounter(moby, (short *)(d + 0x60));
        }
    }
    ((unsigned char *)moby)[0xA4] = 0xFF;
    StepColorFade(moby, d + 0x60);
}

/* Counts the live level-0x75E mobys among the 20 slots at +0xB0 and returns the last slot not counted. */
int refresh_spawner_population_and_find_free_slot(int unused, char *m) {
    int last = -1;
    int i;
    char **slot;
    m[0x91] = count_active_moby_group_members(*(int *)(m + 0x94), -1);
    for (i = 0, slot = (char **)(m + 0xB0); i < 20; i++, slot++) {
        char *o = *slot;
        if (o != 0 && *(short *)(o + 0xA6) == 0x75E && (unsigned char)o[0x20] != 0xFE &&
            (unsigned char)o[0x20] != 0xFD) {
            m[0x91]++;
        } else {
            last = i;
        }
    }
    return last;
}
