/* Bounce a bubble off what it hit: slow on floors until it stops, play its bounce sound. */
static inline void bubble_bounce(struct Moby *moby, BubbleVars *vars) {
    CollisionHit *hit = &gaspar_coll_hit;

    if (hit->moby == 0) {
        reflect_vector(&vars->vel, &vars->vel, &hit->normal.f[0]);
        if (fast_atan2(hit->normal.f[2], vector_length_xy(&hit->normal.f[0])) < 0.6981317f && CollType() == -1) {
            FastVecScale(&vars->vel, &vars->vel, 0.5f);
            if (FastVecLength(&vars->vel) < 0.025f) {
                moby->state = 1;
            }
        }
    } else if (((struct Moby *)hit->moby)->oclass != MOBY_CLASS_SPAWNER_EGG) {
        reflect_vector(&vars->vel, &vars->vel, &hit->normal.f[0]);
        if (fast_atan2(hit->normal.f[2], vector_length_xy(&hit->normal.f[0])) < 0.6981317f && CollType() == -1) {
            FastVecScale(&vars->vel, &vars->vel, 1.2f);
        }
    } else {
        vars->vel.f[2] *= random_float_between(0.9f, 1.1f);
    }
    if (vars->sound_delay == 0) {
        Moby_PlaySound(0, 0, moby);
        vars->sound_delay = 12;
    }
}

/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/shared/gameplay/vendor/00307ba8.c, FUN_L09_0030b3b0. */
void spawner_egg_update(struct Moby *moby) {
    BubbleVars *vars = (BubbleVars *)moby->pvars;
    Vec4 prev;
    Vec4 step;
    Vec4 away;
    BubbleOwnerVars *owner;
    struct Moby *other;
    struct Moby *held;
    s32 i;
    f32 dist;
    f32 rate;

    fast_subtract_rotations_cf(&vars->sound_delay);
    qcopy(&prev, &moby->pos);
    switch (moby->state) {
        case 0:
            moby->scale += (moby->pclass->scale - moby->scale) * (frame_scale * 0.05f);
            FastVecAdd(&moby->pos, &moby->pos, &vars->vel);
            vec_scale_to_length(&step, &vars->vel, 0.2f);
            FastVecAdd(&step, &step, &moby->pos);
            moby->collision = 0;
            vars->owner->collision = 0;
            if (coll_line(&prev, &step, 4, moby, 0) != 0) {
                FastVecSub(&step, &gaspar_coll_hit.point, &step);
                vec_scale_to_length(&step, &step, 0.215f);
                FastVecAdd(&moby->pos, &moby->pos, &step);
                bubble_bounce(moby, vars);
            }
            if (coll_sphere(0.2f, &moby->pos, 4, moby) != 0) {
                FastVecSub(&step, &gaspar_coll_hit.point, gaspar_coll_hit.pushed.f);
                vec_scale_to_length(&step, &step, 0.015f);
                FastVecAdd(&moby->pos, gaspar_coll_hit.pushed.f, &step);
                bubble_bounce(moby, vars);
            }
            owner = (BubbleOwnerVars *)vars->owner->pvars;
            for (i = 0; i < 20; i++) {
                other = owner->bubbles[i];
                if (other != moby && other != 0 && other->oclass == MOBY_CLASS_SPAWNER_EGG && other->state != 0xFE &&
                    other->state != 0xFD) {
                    FastVecSub(&away, &moby->pos, &other->pos);
                    away.f[2] = 0.0f;
                    dist = FastVecLength(&away);
                    if (dist < 1.8f) {
                        FastVecScale(&away, &away, (1.8f - dist) * (frame_scale * -0.5f + 1.0f));
                        FastVecAdd(&moby->pos, &moby->pos, &away);
                    }
                }
            }
            if (FastDecTimer(&vars->life) != 0) {
                moby->state = 2;
            }
            moby->rot.x = normalize_angle(vars->vel.f[0]);
            moby->rot.y = normalize_angle(vars->vel.f[1]);
            moby->collision = moby->pclass->collision;
            vars->owner->collision = vars->owner->pclass->collision;
            vars->vel.f[2] -= g_frame_time_sq * 9.8f;
            moby->rot.x += frame_scale * 0.01f;
            moby->rot.y += frame_scale * 0.02f;
            break;
        case 1:
            moby->pos.z = probe_ground_height(&moby->pos, 0, 0.5f) + 0.2f;
            moby->pos.w = 0.0f;
            step.q = ((Vec4 *)&moby->pos)->q;
            vars->held = respawn_spawner_child(vars->owner, &step);
            moby->state = 2;
            break;
        case 2:
            rate = frame_scale * 0.05f;
            moby->scale -= moby->scale * rate;
            if (vars->held != 0 && vars->unk1A != 0) {
                vars->held->scale += (vars->held->pclass->scale - vars->held->scale) * rate;
            }
            if (moby->scale < moby->pclass->scale * (frame_scale * 0.05f)) {
                moby->scale = 0.0001f;
                held = vars->held;
                if (held == 0 || held->state == 0xFE || held->state == 0xFD || vars->unk1A == 0 ||
                    held->pclass->scale - 0.01f <= held->scale) {
                    remove_spawner_egg(moby, (char *)vars);
                }
            }
            break;
    }
    jet_animate(moby, moby->scale * 0.3f / moby->pclass->scale);
    if (moby->pos.z < 5.0f || moby->pos.z > 500.0f) {
        remove_spawner_egg(moby, (char *)vars);
        return;
    }
    if (moby->pos.x < 5.0f) {
        moby->pos.x = 5.0f;
    }
    if (moby->pos.x > 1018.0f) {
        moby->pos.x = 1018.0f;
    }
    if (moby->pos.y < 5.0f) {
        moby->pos.y = 5.0f;
    }
    if (moby->pos.y > 1018.0f) {
        moby->pos.y = 1018.0f;
    }
    if (moby->pos.z < 5.0f) {
        moby->pos.z = 5.0f;
    }
    if (moby->pos.z > 1018.0f) {
        moby->pos.z = 1018.0f;
    }
}
